class Solution {
    public void reorderList(ListNode head) {
        if (head == null || head.next == null) {
            return;
        }

        ListNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode second = slow.next;
        slow.next = null;
        ListNode prev = null;
        while (second != null) {
            ListNode next = second.next;
            second.next = prev;
            prev = second;
            second = next;
        }
        second = prev;

        ListNode first = head;
        while (second != null) {
            ListNode nextFirst = first.next;
            ListNode nextSecond = second.next;
            first.next = second;
            second.next = nextFirst;
            first = nextFirst;
            second = nextSecond;
        }
    }
}

class Solution {
    public void reorderList(ListNode head) {
        if (head == null) {
            return;
        }

        Deque<ListNode> deque = new ArrayDeque<>();
        ListNode curr = head.next;
        while (curr != null) {
            deque.addLast(curr);
            curr = curr.next;
        }

        curr = head;
        boolean fromBack = true;
        while (!deque.isEmpty()) {
            ListNode node = fromBack ? deque.pollLast() : deque.pollFirst();
            curr.next = node;
            curr = node;
            fromBack = !fromBack;
        }
        curr.next = null;
    }
}

class Solution {
    private ListNode front;

    public void reorderList(ListNode head) {
        front = head;
        reorderFromTail(head);
    }

    private boolean reorderFromTail(ListNode right) {
        if (right == null) {
            return true;
        }
        if (!reorderFromTail(right.next)) {
            return false;
        }
        if (front == right || front.next == right) {
            right.next = null;
            return false;
        }

        ListNode nextFront = front.next;
        front.next = right;
        right.next = nextFront;
        front = nextFront;
        return true;
    }
}

class Solution {
    public void reorderList(ListNode head) {
        if (head == null || head.next == null) {
            return;
        }

        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        Deque<ListNode> stack = new ArrayDeque<>();
        ListNode curr = slow.next;
        slow.next = null;
        while (curr != null) {
            stack.push(curr);
            curr = curr.next;
        }

        ListNode first = head;
        while (!stack.isEmpty()) {
            ListNode later = stack.pop();
            ListNode next = first.next;
            first.next = later;
            later.next = next;
            first = next;
        }
    }
}
